"""Authored scenario sets. Each concept contains ten different decisions, not name-swapped question variants.
This is offline content assembly, never runtime question generation.
"""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
TOPICS = []
def topic(stage, slug, title, source, *cells):
    assert len(cells) == 5, title
    TOPICS.append((stage, slug, title, source, cells))
def cell(title, choices, cases):
    # Four mutually distinguished mechanisms, each with its instructional explanation.
    choices = [tuple(v.split('~', 1)) for v in choices.split('|')]
    cases = [(int(line[0]), line[2:]) for line in cases.strip().split('\n')]
    assert len(choices) == 4 and len(cases) == 10, (title, len(cases))
    return title, choices, cases

